'use strict';
// Route planning uses the actual campus colliders and both staircases.
window.makeCampusNavigator=function(D){
const P=D.plan,X=x=>(x-715)*P.scale,Z=y=>(y-360)*P.scale,px=x=>x/P.scale+715,py=z=>z/P.scale+360,grids=[],pathCache=new Map();
 function grid(level){if(grids[level])return grids[level];const step=8,minX=-88,minY=40,nx=214,ny=101,walk=new Uint8Array(nx*ny);for(let b=0;b<ny;b++)for(let a=0;a<nx;a++)walk[b*nx+a]=Number(D.canMove(X(minX+a*step),Z(minY+b*step),level*P.storey,true));return grids[level]={step,minX,minY,nx,ny,walk};}
 function cell(g,x,y){const a=Math.round((x-g.minX)/g.step),b=Math.round((y-g.minY)/g.step);for(let radius=0;radius<20;radius++)for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){if(Math.max(Math.abs(dx),Math.abs(dy))!==radius)continue;const aa=a+dx,bb=b+dy,k=bb*g.nx+aa;if(aa>=0&&bb>=0&&aa<g.nx&&bb<g.ny&&g.walk[k])return k;}return null;}
 function routeFloor(from,to,level){const g=grid(level),a=cell(g,from.x,from.y),b=cell(g,to.x,to.y);if(a===null||b===null)return [];const key=level+':'+a+':'+b;if(pathCache.has(key))return pathCache.get(key).map(p=>({...p}));const prev=new Int32Array(g.walk.length).fill(-1),queue=new Int32Array(g.walk.length);let head=0,tail=1;queue[0]=a;prev[a]=a;while(head<tail&&prev[b]<0){const k=queue[head++],x=k%g.nx,y=Math.floor(k/g.nx);for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const xx=x+dx,yy=y+dy,n=yy*g.nx+xx;if(xx<0||yy<0||xx>=g.nx||yy>=g.ny||!g.walk[n]||prev[n]>=0)continue;prev[n]=k;queue[tail++]=n;}}
 if(prev[b]<0)return [];const cells=[];for(let k=b;;k=prev[k]){cells.push(k);if(k===a)break;}cells.reverse();const points=cells.filter((k,i)=>!i||i===cells.length-1||cells[i]-cells[i-1]!==cells[i+1]-cells[i]).map(k=>({x:g.minX+k%g.nx*g.step,y:g.minY+Math.floor(k/g.nx)*g.step,h:level*P.storey}));const smooth=[points[0]];for(let i=0;i<points.length-1;){let next=i+1;for(let j=i+2;j<points.length;j++){const f=points[i],t=points[j],steps=Math.ceil(Math.hypot(X(t.x)-X(f.x),Z(t.y)-Z(f.y))/.08);let clear=true;for(let n=1;n<=steps;n++)if(!D.canMove(X(f.x+(t.x-f.x)*n/steps),Z(f.y+(t.y-f.y)*n/steps),level*P.storey,true)){clear=false;break;}if(!clear)break;next=j;}smooth.push(points[next]);i=next;}pathCache.set(key,smooth);return smooth.map(p=>({...p}));}
 function makeRoute(a,target){const currentLevel=a.h>P.storey/2?1:0;if(currentLevel===target.level)return routeFloor(a,target,target.level);const up=target.level===1,candidates=[];
 for(const stair of D.stairModels){const left=px(stair.sx+.08+stair.flight/2),right=px(stair.sx+stair.w-stair.flight/2-.08),landing=py(stair.sz+stair.landing/2),entryY=stair.id==='A'?205:py(stair.sz+stair.d+.35),ends=[{x:left,y:entryY,h:0},{x:right,y:entryY,h:P.storey}],start=ends[up?0:1],finish=ends[up?1:0],before=routeFloor(a,start,currentLevel),after=routeFloor(finish,target,target.level);if(!before.length||!after.length)continue;const cross=[{...start},{x:start.x,y:landing,h:P.storey/2,stair:stair.id},{x:finish.x,y:landing,h:P.storey/2,stair:stair.id},{...finish,stair:stair.id}],path=before.concat(cross,after);let length=0;for(let i=1;i<path.length;i++)length+=Math.hypot(path[i].x-path[i-1].x,path[i].y-path[i-1].y);candidates.push({path,length});}return candidates.sort((a,b)=>a.length-b.length)[0]?.path||[];}

return {routeFloor,makeRoute};
};
